window.docContents[113].resolve({"/rules/RG1004/#RG1004-limitations":{"contents":"The editor may defer authentication and report a pending result; the project command completes it.\n\nAn unauthenticated axiom that merely looks native is not compiler-trusting; it is rejected as an unknown axiom (RG1003) or project axiom (RG1001).\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1004: Compiler-trusting proofs require separate classification","header":"Limitations and unsupported cases","id":"/rules/RG1004/#RG1004-limitations"},"/rules/RG2003/#RG2003-limitations":{"contents":"lake lint builds with Regula's audit-build marker, which turns the local linter off whatever the source sets linter.regula to, so Regula's own local findings are not build warnings there and its policy stages report those rules. axiomGate and the build-lint policy target keep ordinary options, so in a module that imports Regula.Linter a local Regula finding is a build warning and makes the result INCOMPLETE under this rule.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2003: Claimed source must elaborate warning-free","header":"Limitations and unsupported cases","id":"/rules/RG2003/#RG2003-limitations"},"/rules/RG3002/#RG3002-limitations":{"contents":"Proof search is deliberately incomplete: a candidate whose remaining premises cannot be instantiated supplies no evidence, and the boundary stays trusted.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG3002: Checked execution requires admitted correspondence","header":"Limitations and unsupported cases","id":"/rules/RG3002/#RG3002-limitations"},"/rules/RG4001/#RG4001-limitations":{"contents":"Only Markdown structure is checked here; elaboration results belong to RG4002–RG4004.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4001: Documentation fences must have a valid classification","header":"Limitations and unsupported cases","id":"/rules/RG4001/#RG4001-limitations"}});